-- Patient Safety & Quality Improvement: Part 3 (Questions 101-150)
-- US MD / MBBS / USMLE Step 3
-- Target: Supabase (PostgreSQL)
-- Topic Slug: ethics-patient-safety

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-patient-safety' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic slug ethics-patient-safety not found.';
    END IF;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- QI MODELS (PDSA, LEAN, SIX SIGMA)
    (v_topic_id, 'Which phase of the PDSA cycle involves identifying the problem, stating the goal, and defining the measures for success?', '["Plan", "Do", "Study", "Act"]', 0, 'The "Plan" phase is where the problem is analyzed, the change is designed, and the data collection plan is established.'),
    (v_topic_id, 'In a PDSA cycle, "Do" refers to:', '["Finalizing the hospital budget", "Running a small-scale test of the change and collecting data", "Publishing the results in a journal", "Hiring new staff"]', 1, 'The "Do" phase is a small-scale pilot or test of the change to see how it performs in a real-world setting.'),
    (v_topic_id, 'What happens during the "Study" (or Check) phase of the PDSA cycle?', '["The change is implemented permanently", "The data is analyzed and compared to the original hypothesis", "Staff are fired for errors", "A new problem is identified"]', 1, 'In the "Study" phase, the team reviews the results of the test to see if the change led to the desired improvement.'),
    (v_topic_id, 'The "Act" phase of the PDSA cycle involves:', '["Repeating the same test again", "Deciding to adopt, adapt, or abandon the change", "Ignoring the results", "Writing a press release"]', 1, 'Based on the findings from the "Study" phase, the team decides whether to fully implement the change, modify it and re-test, or discard it.'),
    (v_topic_id, 'Which of the following is a core principle of Lean Methodology in healthcare?', '["Increasing the number of forms to sign", "Eliminating waste (non-value-added steps)", "Maximizing the variation in clinical practice", "Increasing the length of patient stay"]', 1, 'Lean focuses on maximizing value for the patient by eliminating "waste" (Muda) such as waiting, rework, and unnecessary motion.'),

    -- LEAN WASTE (TIM WOOD)
    (v_topic_id, 'In Lean terms, "Rework" (e.g., repeating a blood draw because the sample was lost) is an example of which type of waste?', '["Defects", "Overproduction", "Inventory", "Motion"]', 0, 'Defects or errors that require correction or repetition are a major source of waste in Lean.'),
    (v_topic_id, 'Patients waiting for 2 hours in a clinic lobby is considered which type of Lean waste?', '["Waiting", "Transportation", "Over-processing", "Inventory"]', 0, 'Waiting is any time when a patient or staff member is idle due to a lack of resources, information, or coordination.'),
    (v_topic_id, 'A hospital carrying 6 months worth of surgical supplies in a small closet is an example of which Lean waste?', '["Inventory", "Motion", "Defects", "Waiting"]', 0, 'Excessive inventory ties up capital and space, and increases the risk of items expiring before use.'),
    (v_topic_id, 'Lean methodology was originally developed by which organization?', '["NASA", "Toyota", "The World Health Organization", "The Mayo Clinic"]', 1, 'Lean was adapted from the Toyota Production System (TPS) for use in healthcare and other service industries.'),
    (v_topic_id, 'A "Value Stream Map" in Lean is used to:', '["Track the hospital''s stock portfolio", "Visualize every step in a process to identify waste and improve flow", "Assign tasks to the nursing staff", "Measure the cost of a single medication"]', 1, 'Value stream mapping allows teams to see the "big picture" of a process and identify where value is added and where waste occurs.'),

    -- SIX SIGMA VARIATION
    (v_topic_id, 'The primary goal of Six Sigma methodology is to:', '["Reduce waste", "Reduce variation and defects in a process", "Increase the number of staff", "Shorten the work day"]', 1, 'Six Sigma uses data and statistical tools to make a process highly predictable and reliable (3.4 defects per million).'),
    (v_topic_id, 'In Six Sigma, the "DMAIC" acronym stands for:', '["Describe, Measure, Analyze, Implement, Check", "Define, Measure, Analyze, Improve, Control", "Data, Management, Action, Integration, Cost", "Design, Monitor, Audit, Improve, Close"]', 1, 'DMAIC is the structured problem-solving framework used in Six Sigma projects.'),
    (v_topic_id, 'Which quality tool is used to identify the "vital few" causes of a problem?', '["Pareto Chart", "Scatter Plot", "Control Chart", "Flowchart"]', 0, 'The Pareto Chart (80/20 rule) helps teams focus on the small number of causes that result in the majority of errors or delays.'),
    (v_topic_id, 'A "Standard Operating Procedure" (SOP) is an intervention primarily designed to:', '["Increase clinician creativity", "Reduce variation and ensure consistent performance of a task", "Decrease the hospital budget", "Satisfy insurance companies"]', 1, 'SOPs standardize work so that the outcome is the same regardless of who performs it.'),
    (v_topic_id, 'True or False: Lean and Six Sigma are often used together (Lean Six Sigma) to improve both efficiency and reliability.', '["True", "False"]', 0, 'Combining the two allows organizations to eliminate waste while also ensuring high-quality, reliable outcomes.'),

    -- DONABEDIAN MODEL (STRUCTURE, PROCESS, OUTCOME)
    (v_topic_id, 'In the Donabedian Model, "Structure" refers to:', '["What is actually done to and for the patient", "The context in which care is delivered (staff, facilities, equipment)", "The end result of the care provided", "The billing process"]', 1, 'Structure includes the physical environment, organizational culture, staffing levels, and technology available.'),
    (v_topic_id, 'Which of the following is a "Process Measure"?', '["The mortality rate after surgery", "The percentage of diabetic patients who received an HbA1c test", "The number of ICU beds available", "The patient''s quality of life after treatment"]', 1, 'Process measures track whether the correct evidence-based actions were taken during care.'),
    (v_topic_id, 'An "Outcome Measure" in the Donabedian Model is:', '["The number of nurses on a shift", "Whether a checklist was used during surgery", "The 30-day readmission rate for heart failure patients", "The availability of an electronic health record"]', 2, 'Outcomes are the results of care, such as complication rates, mortality, or patient functional status.'),
    (v_topic_id, 'Why is "Staffing Ratio" (e.g., 1 nurse to 2 patients) considered a Structure measure?', '["Because it is easy to count", "Because it is an organizational attribute that creates the conditions for care", "Because it is an end result", "Because it is a medical procedure"]', 1, 'Staffing is part of the "scaffolding" or structure that supports the delivery of care.'),
    (v_topic_id, 'If a QI team wants to know if they are following the rules for hand hygiene, they would measure __________.', '["Structure", "Process", "Outcome", "Balancing"]', 1, 'Hand hygiene compliance (did people wash their hands?) is a process measure.'),

    -- BALANCING MEASURES & SMART GOALS
    (v_topic_id, 'A "Balancing Measure" in quality improvement is used to:', '["Ensure the project stays on budget", "Monitor if the improvement in one area is causing new problems in another", "Calculate the average weight of the staff", "Measure the speed of the intervention"]', 1, 'Balancing measures ensure that a change (e.g., discharging patients faster) doesn''t have a negative side effect (e.g., higher readmission rates).'),
    (v_topic_id, 'A "SMART" goal should be Specific, Measurable, Achievable, Relevant, and:', '["Targeted", "Timely/Time-bound", "Total", "Transparent"]', 1, 'Goals must have a clear timeframe for completion to ensure accountability and focus.'),
    (v_topic_id, 'Which of the following is a SMART goal?', '["We will improve our hand hygiene compliance as soon as possible", "We will increase hand hygiene compliance from 60% to 90% in the ICU by June 1, 2026", "Doctors should try harder to wash their hands", "We want to be the best hospital in the state"]', 1, 'This goal is specific, measurable, achievable, relevant, and time-bound.'),
    (v_topic_id, 'What is the "Aim Statement" in a quality improvement project?', '["A list of everyone''s job titles", "A formal summary of what the project intends to achieve, for whom, and by when", "A budget request for new equipment", "A description of the error that started the project"]', 1, 'The aim statement provides the "North Star" for the QI team.'),
    (v_topic_id, 'A "Global Aim" is a broad goal, while a "Specific Aim" is __________.', '["A goal for only one doctor", "A more focused, measurable target within the global aim", "A goal that changes every day", "A goal that doesn''t require data"]', 1, 'Specific aims are the actionable targets that contribute to the larger organizational goal.'),

    -- DATA TOOLS (RUN CHARTS & CONTROL CHARTS)
    (v_topic_id, 'A "Run Chart" is a graph of data points plotted over __________.', '["Cost", "Time", "Severity", "Age"]', 1, 'Run charts are essential for visualizing trends, shifts, and cycles in a process over time.'),
    (v_topic_id, 'In a run chart, a "Shift" is defined as __________ or more consecutive points on one side of the median.', '["2", "4", "6 (or 8, depending on the rule used)", "10"]', 2, 'A shift indicates a non-random change in the process that warrants investigation.'),
    (v_topic_id, 'A "Control Chart" (Shewhart chart) adds __________ to a run chart.', '["Upper and lower statistical control limits", "The names of the staff involved", "The total cost of the project", "Pictures of the patients"]', 0, 'Control limits help distinguish between "common cause" variation (natural noise) and "special cause" variation (unusual events).'),
    (v_topic_id, '"Common Cause" variation is variation that is:', '["Unpredictable and due to a specific event", "Inherent in the system and predictable", "Always a sign of a bad system", "Easy to eliminate with a single rule"]', 1, 'Common cause variation is the normal "background noise" of a stable system.'),
    (v_topic_id, '"Special Cause" variation is variation that is:', '["Inherent in the system", "Due to a specific, non-random factor outside the normal process", "Unimportant", "Impossible to find"]', 1, 'Special causes (e.g., a power outage or a new untrained staff member) require targeted investigation.'),

    -- BENCHMARKING & ACCOUNTABILITY
    (v_topic_id, 'A "Key Performance Indicator" (KPI) is a metric that is:', '["Used only for billing", "Essential for measuring the success of an organization in reaching its goals", "Secret information for the CEO only", "A measure of the hospital''s size"]', 1, 'KPIs provide a snapshot of the most critical aspects of organizational performance.'),
    (v_topic_id, 'The "HCAHPS" survey is a standardized tool used in the US to measure:', '["Clinical outcomes of surgery", "The hospital''s financial health", "The patient''s experience and satisfaction with their care", "The number of infections in the ICU"]', 2, 'HCAHPS scores are publicly reported and can influence hospital reimbursement.'),
    (v_topic_id, 'What is the purpose of "Risk Adjustment" when reporting mortality rates?', '["To make the hospital look better than it is", "To account for differences in patient severity of illness and comorbidities when comparing hospitals", "To hide errors", "To increase the cost of insurance"]', 1, 'Without risk adjustment, hospitals that take on the most difficult cases would be unfairly penalized.'),
    (v_topic_id, 'A "Balanced Scorecard" in healthcare includes metrics for:', '["Clinical Quality and Safety", "Patient Experience", "Financial Performance", "All of the above"]', 3, 'A balanced approach ensures that one area (e.g., finance) is not prioritized at the expense of others (e.g., safety).'),
    (v_topic_id, 'Transparency in reporting quality data is primarily intended to:', '["Punish low-performing doctors", "Empower patients and drive organizational improvement", "Confuse the public", "Reduce the amount of care provided"]', 1, 'Transparency makes performance visible, encouraging accountability and excellence.'),

    -- QI INTERVENTIONS
    (v_topic_id, 'Which of the following is a "Strong" QI intervention (more likely to succeed)?', '["Mandatory training videos", "A memo from the Chief Medical Officer", "Standardizing equipment and implementing forcing functions", "Posting a list of \"Rules for Safety\" on the wall"]', 2, 'System redesign (standardization, forcing functions) is more effective than education or "reminders" which rely on human vigilance.'),
    (v_topic_id, 'A "Checklist" is most effective when it is:', '["Long and includes every possible task", "Short, actionable, and used by the whole team together", "Filled out by a single person after the procedure is over", "Stored in a drawer and never looked at"]', 1, 'Effective checklists facilitate communication and ensure that critical "never-skip" steps are performed.'),
    (v_topic_id, 'In the "Culture of Safety," "Situational Awareness" refers to:', '["Knowing where the nearest exit is", "The team''s shared understanding of what is happening and what might happen next", "The patient''s awareness of their diagnosis", "The insurance company''s knowledge of the hospital"]', 1, 'Situational awareness allows a team to anticipate and prevent errors before they occur.'),
    (v_topic_id, 'A "Briefing" (or Huddle) occurs __________ a task to plan and coordinate.', '["Before", "During", "After", "Monthly"]', 0, 'Briefings set the stage for safe performance by aligning the team on the plan and potential risks.'),
    (v_topic_id, 'A "Debriefing" occurs __________ a task to review performance and learn.', '["Before", "During", "After", "Annually"]', 2, 'Debriefings are critical for continuous learning and identifying system improvements after an event or shift.'),

    -- MISC QI CONCEPTS
    (v_topic_id, 'The "Spread" of a quality improvement refers to:', '["The cost of the project", "Implementing a successful change from one unit to the rest of the organization", "The time it takes to see results", "The number of errors reported"]', 1, 'Spread is the process of scaling up a successful pilot to achieve broad impact.'),
    (v_topic_id, 'A "Pilot Study" is another name for which part of the PDSA cycle?', '["Plan", "Do", "Study", "Act"]', 1, 'The "Do" phase is a pilot test of the change.'),
    (v_topic_id, 'What is the "Ideal" number of patients for the first "Do" cycle in a new QI project?', '["1,000", "100", "A very small number (e.g., 1 to 5)", "All patients in the hospital"]', 2, 'Starting small (e.g., one patient, one shift, one doctor) allows for rapid learning and adjustment without widespread risk.'),
    (v_topic_id, 'A "Force Field Analysis" is used in QI to identify:', '["The gravitational pull of the hospital", "Drivers for and barriers against a proposed change", "The electrical load of the ICU", "The speed of the pharmacy delivery robot"]', 1, 'This tool helps teams understand what will help or hinder their implementation of a new process.'),
    (v_topic_id, 'True or False: Quality improvement is a one-time project with a fixed end date.', '["True", "False"]', 1, 'QI is a continuous, iterative process of seeking and implementing improvements.'),

    -- MORE DONABEDIAN 모델
    (v_topic_id, 'Which of the following is a "Process Measure" for stroke care?', '["The number of neurologists on staff", "The percentage of eligible patients receiving TPA within 60 minutes", "The 90-day disability score (Rankin Scale)", "The cost of a CT scan"]', 1, 'Door-to-needle time is a critical process measure in stroke care.'),
    (v_topic_id, 'A hospital building a new surgical wing is an investment in __________.', '["Structure", "Process", "Outcome", "None of the above"]', 0, 'New facilities are structural improvements.'),
    (v_topic_id, 'Which measure is most sensitive to the "acuity" of the patient population?', '["Process", "Outcome (e.g., Mortality)", "Structure", "All are equally sensitive"]', 1, 'Outcomes are highly influenced by the patient''s baseline health and severity of illness.'),
    (v_topic_id, 'If a hospital has a 100% compliance rate with handwashing but a high rate of infections, the team should look at __________.', '["The accuracy of the process measurement", "Other processes or structural factors contributing to infection", "Both A and B", "Neither; the data is wrong"]', 2, 'Safety is multi-factorial; if one process is perfect but outcomes are poor, other causes must be explored.'),
    (v_topic_id, 'The "Standard of Care" is a __________ measure.', '["Structure", "Process", "Outcome", "Legal"]', 1, 'Standard of care typically defines the processes (actions) that are expected for a given condition.')
END $$;
